// ============================================
// CONFIGURABLE VARIABLES — edit these values
// ============================================
const GITHUB_OWNER   = 'YOUR_ORG';          // GitHub org or user
const GITHUB_REPO    = 'YOUR_REPO';          // Repository name
const GITHUB_TOKEN   = 'ghp_xxxxxxxxxxxx';   // GitHub PAT (repo scope)
const CLAUDE_API_KEY = 'sk-ant-xxxxxxxxxx';  // Anthropic API key
const LANGUAGE       = 'en';                 // 'en' or 'fr'

// Delivery: 'webhook' sends to Discord/Slack webhook URL
const DELIVERY_METHOD = 'webhook';
const WEBHOOK_URL     = 'https://discord.com/api/webhooks/XXXX/YYYY';
// For Slack: use https://hooks.slack.com/services/T.../B.../xxx
// For email: change DELIVERY_METHOD to 'email' and set SMTP creds in n8n

// ============================================
const since = new Date(Date.now() - 7*24*60*60*1000).toISOString();
const weekLabel = since.slice(0,10) + ' → ' + new Date().toISOString().slice(0,10);

return [{ json: { GITHUB_OWNER, GITHUB_REPO, GITHUB_TOKEN, CLAUDE_API_KEY,
                   LANGUAGE, DELIVERY_METHOD, WEBHOOK_URL, since, weekLabel } }];

const body = $input.first().json.body || $input.first().json;
const since = $('Set Config').item.json.since;
const commits = (Array.isArray(body) ? body : []).filter(
  c => new Date(c.commit.author.date) >= new Date(since)
).map(c => ({
  message: c.commit.message.split('\n')[0],
  author: c.commit.author.name,
  date: c.commit.author.date.slice(0,10),
  sha: c.sha.slice(0,7)
}));
return [{ json: { ...$('Set Config').item.json, commits } }];

const body = $input.first().json.body || $input.first().json;
const since = $('Store Commits').item.json.since;
const issues = (Array.isArray(body) ? body : []).filter(
  i => !i.pull_request && new Date(i.closed_at) >= new Date(since)
).map(i => ({
  title: i.title, number: i.number,
  labels: (i.labels||[]).map(l => l.name)
}));
return [{ json: { ...$('Store Commits').item.json, issues } }];

const body = $input.first().json.body || $input.first().json;
const cfg = $('Store Issues').item.json;
const since = new Date(cfg.since);
const prs = (Array.isArray(body) ? body : []).filter(
  p => p.merged_at && new Date(p.merged_at) >= since
).map(p => ({
  title: p.title, number: p.number, author: p.user?.login || 'unknown'
}));
return [{ json: { ...cfg, prs } }];

