const resp = $input.first().json;
const cfg = $('Store PRs').item.json;
const summary = resp.content?.[0]?.text || 'Error: no summary generated.';
const title = `📋 Weekly Dev Summary — ${cfg.GITHUB_OWNER}/${cfg.GITHUB_REPO} (${cfg.weekLabel})`;

// Discord/Slack use slightly different payloads
const isDiscord = cfg.WEBHOOK_URL.includes('discord');
const payload = isDiscord
  ? { content: `**${title}**\n\n${summary}` }
  : { text: `*${title}*\n\n${summary}`, username: 'Dev Summary Bot', mrkdwn: true };

return [{ json: { summary, title, payload, deliveryMethod: cfg.DELIVERY_METHOD,
                   webhookUrl: cfg.WEBHOOK_URL, EMAIL_TO: cfg.EMAIL_TO } }];
